\title{Diophantine Approximation and the Lagrange Constant:\\
Unbounded Denominators, a Universal Bound, and the\\
Vanishing of the Lagrange Constant on Liouville Numbers}
\author{Aristotle}
\date{2026-06-28}

\begin{document}
\maketitle

\begin{abstract}
We develop the quantitative theory connecting classical Diophantine approximation to
the \emph{Lagrange (approximation) constant} of a real number. Building on the classical
theorem that every irrational $x$ admits infinitely many rationals $p/q$ with
$|x - p/q| < 1/q^2$, we first establish a strengthening essential for all asymptotic
arguments: the denominators of these Dirichlet-good approximations are unbounded.
Concretely, for every irrational $x$ and every $N \in \N$ there is a rational $q$ in
lowest terms with denominator at least $N$ satisfying $|x - q| < 1/q.\den^2$. The proof
rests on a local finiteness principle: within any bounded interval, only finitely many
rationals have denominator below a fixed bound. We then define the Lagrange constant
$\Lc(x) = \liminf_{q \to \infty} q \cdot \nrm{q x}$, valued in the extended nonnegative
reals, where $\nrm{\cdot}$ denotes distance to the nearest integer, and the set of
\emph{badly approximable} reals $\mathrm{Bad} = \{x : \Lc(x) > 0\}$. We prove two
endpoint results. First, the \emph{universal bound}: every irrational satisfies
$\Lc(x) \le 1$, a direct consequence of unbounded denominators and the easy half of
Hurwitz's theorem. Second, the \emph{vanishing theorem}: every Liouville number
satisfies $\Lc(x) = 0$, whence no Liouville number is badly approximable. Together these
results furnish a clean dictionary between approximation quality and position on the
Lagrange spectrum. All results have been formally verified.
\end{abstract}

\section{Introduction}

Diophantine approximation studies how accurately real numbers can be approximated by
rationals, measured against the denominator. The foundational result is
\textbf{Dirichlet's approximation theorem}: for every irrational $x$ there exist
infinitely many rationals $p/q$ (in lowest terms, $q \ge 1$) with
\begin{equation}
\left| x - \frac{p}{q} \right| < \frac{1}{q^2}. \label{eq:dirichlet}
\end{equation}
\textbf{Hurwitz's theorem} sharpens the constant: $1/(\sqrt{5}\,q^2)$ holds infinitely
often for every irrational, with $\sqrt 5$ optimal and attained by the golden ratio
$\varphi = (1+\sqrt 5)/2$. At the opposite extreme, \textbf{Liouville's theorem} (1844)
exhibits numbers too well approximated by rationals to be algebraic, producing the first
explicit transcendentals.

For a real number $x$, write $\nrm{y}$ for the distance from $y$ to the nearest integer
and define the \textbf{Lagrange constant}
\begin{equation}
\Lc(x) = \liminf_{q \to \infty} q \cdot \nrm{q x}. \label{eq:lc}
\end{equation}
A real number is \textbf{badly approximable} when $\Lc(x) > 0$. The values
$\{\Lc(x) : x \notin \Q\}$ form the \emph{Lagrange spectrum}.

This paper formalizes the foundational bridge between \eqref{eq:dirichlet} and
\eqref{eq:lc}. Our contributions are: (1) unbounded denominators (Section
\ref{sec:unbounded}); (2) the universal bound $\Lc(x) \le 1$ (Section \ref{sec:bound});
(3) vanishing on Liouville numbers (Section \ref{sec:liouville}).

\section{Preliminaries and Definitions}

Throughout, $x \in \R$ is irrational unless stated otherwise. For a rational $q$ we
write $q.\num \in \Z$ and $q.\den \in \N_{\ge 1}$ for its numerator and denominator in
lowest terms, so $\gcd(q.\num, q.\den) = 1$ and $q = q.\num / q.\den$.

\begin{definition}[distance to nearest integer]
For $y \in \R$, set $\nrm{y} = |y - \round(y)|$, where $\round(y)$ is the nearest
integer to $y$. Then $0 \le \nrm{y} \le \tfrac12$, and $\nrm{y} = 0$ iff $y \in \Z$.
Moreover $\nrm{y + n} = \nrm{y}$ for $n \in \Z$ and $\nrm{-y} = \nrm{y}$.
\end{definition}

\begin{definition}[approximation function]
For $x \in \R$ and $q \in \N$, define, valued in $[0,+\infty]$,
$\approxf(x, q) = q \cdot \nrm{q x}$. Working in $[0,+\infty]$ makes the $\liminf$ in
\eqref{eq:lc} unconditionally well-behaved.
\end{definition}

\begin{definition}[Lagrange constant]
$\Lc(x) = \liminf_{q \to \infty} \approxf(x, q)$.
\end{definition}

\begin{definition}[badly approximable set]
$\mathrm{Bad} = \{x \in \R : \Lc(x) > 0\}$.
\end{definition}

\begin{definition}[Dirichlet-good rational]
A rational $q$ is \emph{Dirichlet-good} for $x$ if $|x - q| < 1/q.\den^2$. By
Dirichlet's theorem, the set of Dirichlet-good rationals is infinite for irrational $x$.
\end{definition}

\begin{definition}[Liouville number]
A real number $x$ is a \emph{Liouville number} if for every $n \in \N$ there exist
integers $p, q$ with $q > 1$ and $0 < |x - p/q| < 1/q^{\,n}$. Every Liouville number is
irrational (indeed transcendental).
\end{definition}

\section{Unbounded Denominators}\label{sec:unbounded}

\subsection{Local finiteness}

\begin{lemma}[local finiteness, \texttt{finite\_den\_le\_in\_interval}]\label{lem:finite}
For every $N \in \N$ and all real $a < b$, the set
$\{ q \in \Q : q.\den \le N,\ q \in (a,b) \}$ is finite.
\end{lemma}

\begin{proof}[Proof sketch]
Put $C = \lceil |a| \rceil + \lceil |b| \rceil + 1$, a fixed natural number bounding
$|y|$ for $y \in (a,b)$. For any $q$ in the set, $q \in (a,b)$ gives $|q| \le C$, hence
$|q.\num| = |q|\, q.\den \le C\, q.\den \le C N$. Thus $q \mapsto (q.\num, q.\den)$ maps
the set injectively into the finite product $\{ m \in \Z : |m| \le CN \} \times \{ d \in
\N : 1 \le d \le N \}$. The map is injective since $q = q.\num/q.\den$. A subset of a
finite set is finite. (The case $N = 0$ is vacuous, since denominators are $\ge 1$.)
\end{proof}

\subsection{The unboundedness theorem}

\begin{theorem}[unbounded denominators, \texttt{irrational\_den\_unbounded}]\label{thm:unbounded}
Let $x$ be irrational and $N \in \N$. Then there exists a rational $q$ with
$|x - q| < 1/q.\den^2$ and $N \le q.\den$.
\end{theorem}

\begin{proof}[Proof sketch]
Suppose not. Then every Dirichlet-good $q$ has $q.\den < N$, hence $q.\den \le N$, and
$|x - q| < 1/q.\den^2 \le 1$, so $q \in (x-1, x+1)$. Thus the set of Dirichlet-good
rationals embeds into $\{ q : q.\den \le N,\ q \in (x-1,x+1) \}$, finite by Lemma
\ref{lem:finite}. But that set of Dirichlet-good rationals is infinite, a contradiction.
\end{proof}

\subsection{Coprime form}

\begin{theorem}[coprime approximations, \texttt{irrational\_infinitely\_many\_coprime\_approx}]\label{thm:coprime}
Let $x$ be irrational and $N \in \N$. Then there exist $a \in \Z$ and $b \in \N$ with
$N \le b$, $\gcd(a,b) = 1$, and $|x - a/b| < 1/b^2$.
\end{theorem}

\begin{proof}[Proof sketch]
Apply Theorem \ref{thm:unbounded} to get a Dirichlet-good $q$ with $q.\den \ge N$; set
$a = q.\num$, $b = q.\den$. Coprimality is reducedness of $q$, and the inequality is the
rewriting of $|x - q|$.
\end{proof}

\section{A Universal Bound on the Lagrange Constant}\label{sec:bound}

\begin{theorem}[universal bound, \texttt{Lc\_le\_one\_of\_irrational}]\label{thm:bound}
Every irrational $x$ satisfies $\Lc(x) \le 1$.
\end{theorem}

\begin{proof}[Proof sketch]
We bound the $\liminf$ by exhibiting arbitrarily large denominators $q$ with
$\approxf(x,q) \le 1$. Fix $N$. By Theorem \ref{thm:unbounded} there is a Dirichlet-good
rational with denominator $b \ge N$ and numerator $a$, so $|x - a/b| < 1/b^2$.
Multiplying by $b$, $|bx - a| < 1/b$. Since $a \in \Z$, $\nrm{bx} \le |bx - a| < 1/b$,
whence $\approxf(x,b) = b\,\nrm{bx} < 1$. As $N$ was arbitrary, this holds frequently as
$q \to \infty$, so $\Lc(x) = \liminf_q \approxf(x,q) \le 1$.
\end{proof}

\begin{remark}[toward Hurwitz]
The bound uses one Dirichlet approximation per scale. Hurwitz's theorem yields the sharp
$\Lc(x) \le 1/\sqrt 5$, attained on the $\mathrm{GL}_2(\Z)$-orbit of the golden ratio,
by extracting three consecutive convergents; see Conjecture C1.
\end{remark}

\section{Vanishing on Liouville Numbers}\label{sec:liouville}

\begin{lemma}[\texttt{eq\_zero\_of\_forall\_pos\_le}]\label{lem:squeeze}
If $z \in [0,+\infty]$ satisfies $z \le \varepsilon$ for every $\varepsilon > 0$, then
$z = 0$.
\end{lemma}

\begin{proof}[Proof sketch]
If $z \ne 0$, then $z = +\infty$ contradicts $z \le 1$, and $0 < z < +\infty$ gives the
contradiction $z \le z/2$ at $\varepsilon = z/2$.
\end{proof}

For irrational $x$ and $q \ge 1$ one has $\approxf(x,q) > 0$, since $qx \notin \Z$ and
hence $\nrm{qx} > 0$ (positivity away from the limit).

\begin{theorem}[Liouville vanishing, \texttt{Lc\_eq\_zero\_of\_liouville}]\label{thm:liouville}
If $x$ is a Liouville number then $\Lc(x) = 0$.
\end{theorem}

\begin{proof}[Proof sketch]
By Lemma \ref{lem:squeeze} it suffices to show $\Lc(x) \le \varepsilon$ for all
$\varepsilon > 0$. Fix $\varepsilon > 0$. By the Liouville property with exponent $n$
there are integers $p,q$, $q > 1$, with $0 < |x - p/q| < 1/q^{\,n}$. Multiplying by $q$,
$|qx - p| < q^{\,1-n}$, so $\nrm{qx} < q^{\,1-n}$ and $\approxf(x,q) = q\,\nrm{qx} <
q^{\,2-n} \le 2^{\,2-n}$ for $q \ge 2$, $n \ge 3$, which is $< \varepsilon$ for $n$
large. The Liouville denominators can be forced large (only finitely many small
denominators give such accuracy in a bounded range, cf.\ Lemma \ref{lem:finite}), so the
estimate occurs frequently as $q \to \infty$ and $\liminf_q \approxf(x,q) \le
\varepsilon$. As $\varepsilon$ was arbitrary, $\Lc(x) = 0$.
\end{proof}

\begin{corollary}[\texttt{liouville\_not\_bad}]\label{cor:notbad}
No Liouville number lies in $\mathrm{Bad}$.
\end{corollary}

\begin{proof}[Proof sketch]
If $x$ is Liouville then $\Lc(x) = 0$ by Theorem \ref{thm:liouville}, so $\Lc(x) > 0$
fails.
\end{proof}

\section{Worked Examples}

We illustrate the theory on concrete numbers; the values below are reproduced by the
accompanying demonstrations.

\paragraph{The golden ratio $\varphi = (1+\sqrt 5)/2$.} Its continued fraction is the
all-ones expansion $[1;1,1,\ldots]$, the slowest possible, so its convergents are ratios
of consecutive Fibonacci numbers. The approximations are correspondingly poor:
$\Lc(\varphi) = 1/\sqrt 5 \approx 0.4472$, the spectral maximum. Empirically $\min_{q \le
20000} q\nrm{q\varphi} \approx 0.382$, creeping up toward $1/\sqrt 5$. It is the canonical
badly approximable number, inside the bound of Theorem~\ref{thm:bound}.

\paragraph{The quadratic irrational $\sqrt 2 = [1;2,2,\ldots]$.} Its convergents
$1, \tfrac32, \tfrac75, \tfrac{17}{12}, \ldots$ obey the Pell recurrence and pass
denominator $10^9$ within about twenty terms, an effective instance of
Theorem~\ref{thm:unbounded}; the empirical Lagrange constant settles near $0.343$.

\paragraph{A Liouville number $L = \sum_{k \ge 1} 10^{-k!}$.} Truncating at term $n$ gives
denominator $q = 10^{n!}$ with $q\nrm{qL} \approx 10^{-n\cdot n!}$, collapsing as
$10^{-1}, 10^{-4}, 10^{-18}, 10^{-96}, \ldots$, witnessing $\Lc(L) = 0$
(Theorem~\ref{thm:liouville}) and $L \notin \mathrm{Bad}$
(Corollary~\ref{cor:notbad}).

These examples span the theory: the golden ratio at the top, quadratic irrationals
strictly inside $\mathrm{Bad}$, and Liouville numbers at the vanishing bottom.

\section{Historical Context and Related Work}

Rational approximation is among the oldest threads of number theory. Continued fractions
appear implicitly in Euclid's algorithm and explicitly in Bombelli, Wallis, and Huygens,
the last using convergents for planetarium gear ratios. The modern theory crystallized in
the nineteenth century: Dirichlet's pigeonhole proof of the $1/q^2$ bound (1842),
Liouville's explicit transcendentals (1844), and Hurwitz's sharp $1/\sqrt 5$ (1891). The
Lagrange and Markov spectra of $\Lc$-values grew from Markov's 1879--1880 work on
indefinite binary quadratic forms and remain active, the structure below Freiman's
constant $\approx 4.5278$ being especially intricate. The present development sits at the
elementary foundations: it takes infinitely many Dirichlet-good approximations as given
and contributes the denominator-unboundedness refinement (Theorem~\ref{thm:unbounded})
logically necessary for the passage to asymptotic invariants, then brackets the spectrum
from above and below with Theorems~\ref{thm:bound} and~\ref{thm:liouville}.

\section{Algorithms}

\paragraph{Algorithm A (best rational approximations via continued fractions).}
Compute $x = [a_0; a_1, a_2, \ldots]$ by $a_k = \lfloor x_k \rfloor$, $x_{k+1} =
1/(x_k - a_k)$, and convergents $p_k = a_k p_{k-1} + p_{k-2}$, $q_k = a_k q_{k-1} +
q_{k-2}$. Each convergent satisfies $|x - p_k/q_k| < 1/q_k^2$ with strictly increasing
$q_k$, an explicit witness for Theorem \ref{thm:unbounded}.

\paragraph{Algorithm B (empirical Lagrange constant).}
Evaluate $q \cdot \nrm{q x}$ over $q = 1, \ldots, Q$ and track the running tail minimum;
the minimum over convergent denominators converges to $\Lc(x)$, making Theorems
\ref{thm:bound} and \ref{thm:liouville} numerically visible.

\section{Applications}

Convergents explain the Gregorian leap-year rule (year $\approx 365.2425$), optimal gear
tooth counts, and the equal-tempered fifth $2^{7/12}$. Wiener's attack on RSA with small
private exponent recovers the secret by detecting a too-well-approximated ratio, a
Liouville-like extreme (Theorem \ref{thm:liouville}). Theorem \ref{thm:liouville}
quantifies why Liouville numbers are transcendental: $\Lc = 0$, in contrast to the
positive lower bound conjectured for algebraic irrationals (Conjecture C4).

\section{Discussion}

The three theorems form a dictionary at the two endpoints of the Lagrange spectrum:
Theorem \ref{thm:bound} caps every irrational at $\Lc \le 1$; Theorem
\ref{thm:liouville} sends the most-approximable numbers to $\Lc = 0$. The golden ratio
realizes the top at $1/\sqrt 5$, and $\mathrm{Bad}$ sits strictly between. The
unbounded-denominator theorem converts set-theoretic infinitude into the asymptotic
statements the $\liminf$ definition requires. Valuing $\approxf$ and $\Lc$ in
$[0,+\infty]$ removes boundedness side-conditions at the cost of careful arithmetic with
$+\infty$.

\section{Future Directions}

\begin{itemize}
  \item \textbf{C1 (Hurwitz sharpening).} Strengthen Theorem \ref{thm:bound} to $\Lc(x)
    \le 1/\sqrt 5$ via a three-consecutive-convergent inequality; equality on the
    $\mathrm{GL}_2(\Z)$-orbit of the golden ratio.
  \item \textbf{C2 (modular invariance).} Prove $\Lc(x) = \Lc(y)$ for $y = (ax+b)/(cx+d)$
    with $ad - bc = \pm 1$; the affine $\pm 1$ case is established, leaving $x \mapsto
    -1/x$.
  \item \textbf{C3 (badly approximable $\Leftrightarrow$ bounded partial quotients).}
    Show $\Lc(x) > 0$ iff the partial quotients of $x$ are bounded; Theorem
    \ref{thm:liouville} is the unbounded-quotient extreme.
  \item \textbf{C4 (quantitative Liouville for algebraic numbers).} For real algebraic
    $x$ of degree $d \ge 2$, obtain $c > 0$ with $|x - p/q| > c/q^d$, implying $\Lc(x) >
    0$ for quadratic irrationals.
\end{itemize}

\section{Conclusion}

We have formally verified the foundational bridge from classical Diophantine
approximation to the Lagrange constant: denominators of good approximations are unbounded
(Theorem \ref{thm:unbounded}), every irrational obeys $\Lc(x) \le 1$ (Theorem
\ref{thm:bound}), and Liouville numbers achieve $\Lc(x) = 0$, so they are never badly
approximable (Theorem \ref{thm:liouville}, Corollary \ref{cor:notbad}). These endpoints
anchor the Lagrange spectrum and set the stage for sharper invariance and spectral
results.

